import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"27、【颐】 震下艮上","description":"周易口诀义 - 27、【颐】 震下艮上","frontmatter":{"title":"27、【颐】 震下艮上","description":"周易口诀义 - 27、【颐】 震下艮上"},"headers":[],"relativePath":"zh/classics/koujueyi/029.md","filePath":"zh/classics/koujueyi/029.md"}'),r={name:"zh/classics/koujueyi/029.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_27、【颐】-震下艮上" tabindex="-1">27、【颐】 震下艮上 <a class="header-anchor" href="#_27、【颐】-震下艮上" aria-label="Permalink to “27、【颐】 震下艮上”">​</a></h1><p>彖曰：「颐，贞吉」，养正则吉也。「观颐」，观其所养也。「自求口实」，观其自养也。天地养万物，圣人养贤以及万民，颐之时大矣哉！</p><p>象曰：山下有雷，颐。君子以慎言语，节饮食。</p><p>初九，舍尔灵龟，观我朵颐，凶。</p><p>象曰：「观我朵颐」，亦不足贵也。</p><p>六二，颠颐，拂经，于丘颐，征凶。</p><p>象曰：六二「征凶」，行失类也。</p><p>六三，拂颐，贞凶，十年勿用，无攸利。</p><p>象曰：「十年勿用」，道大悖也。</p><p>六四，颠颐，吉。虎视眈眈，其欲逐逐，无咎。</p><p>象曰：「颠颐」之吉，上施光也。</p><p>六五，拂经，居贞吉，不可涉大川。</p><p>象曰：「居贞」之吉，顺以从上也。</p><p>上九，由颐，厉吉，利涉大川。象曰：「由颐厉吉」，大有庆也。</p><p>解读</p><p>「颐贞吉」者，颐，养也，养正则吉，故曰「颐贞吉」也。「观颐」者，谓在下之人，观其君上所养之人，若所养之人贤良，即能助君行化也。「自求口实」者，谓其自养，求其口中之实物，饮食不节，患必生焉，故荀爽云「饮食失宜，患之所起」是也。象曰「山下有雷，颐」者，艮止于上，雷动于下，犹人口动，咀嚼饮食，皆下动上止，颐之象也。「君子以慎言语，节饮食」者，启发言语，荣辱之阶，不可不慎；饮食过伤，患之所起，不得不节也。</p><p>「初九，舍尔灵龟，观我朵颐，凶」者，「灵龟」，谓神灵明兆之物，喻己之明德；朵，犹动嚼也，喻贪婪躁求。食禄之人，当养贤之初，不能修德待用，而贪羡它人，躁欲求之，如舍已明德，贪窃躁求，所以「凶」也。</p><p>「六二，颠颐，拂经，于丘颐，征凶」者，颠，倒也，谓倒下养初也；拂，违也；经犹义也；丘，所履之常。凡颐养之道，只合以下养上，今既倒下养初，即是违于经义所履之常，以此而养，所行必凶，故曰「颐，征凶」也。</p><p>「六三拂颐，贞凶，十年勿用，无攸利」者，颐养之体，贵于守正，今六三以阴居阳，是纳上以謟媚也。既为謟行，违养之道，是正之凶矣。虽复十年，犹未可见用，故无施而利，故曰「无攸利」也。</p><p>「六四，颠颐，吉。虎视耽耽，其欲逐逐，无咎」者，「耽耽」，威肃也；「逐逐」，敦实也；以上养下，所养贤人，故曰「颠颐，吉」也。亲德养贤也，不可以慢，必须威而不猛，如虎之视近志远，虽不怒而有威，又须寡欲少求，情志逐逐。修此二德，是颐养之美，故「无咎」也。</p><p>「六五：拂经，居贞吉。不可涉大川」者，以阴居阳而位不正，是违经义。若居之能守贞正即吉，以不正之身而处尊位，故「不利涉大川」也。</p><p>上九：由颐，厉吉。「利涉大川」者，四阴皆宗归上，莫不由上九而养之，故曰「由颐」也。为众阴之主，又非其尊位，不可以慢，故严厉乃得吉，故曰「厉吉」。为众之主，既能严正，即物不敢违，故「利涉大川」也。</p>',22)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
